class Solution:
    def minAreaFreeRect(self, points):
        pts = {(x, y) for x, y in points}
        n = len(points)
        best = float('inf')
        for i in range(n):
            x1, y1 = points[i]
            for j in range(n):
                if j == i: continue
                x2, y2 = points[j]
                dx1, dy1 = x2 - x1, y2 - y1
                for k in range(j + 1, n):
                    if k == i: continue
                    x3, y3 = points[k]
                    dx2, dy2 = x3 - x1, y3 - y1
                    if dx1 * dx2 + dy1 * dy2 != 0: continue
                    px, py = x2 + x3 - x1, y2 + y3 - y1
                    if (px, py) in pts:
                        best = min(best, (dx1*dx1 + dy1*dy1) ** 0.5 * (dx2*dx2 + dy2*dy2) ** 0.5)
        return best if best < float('inf') else 0.0

