class Solution {
public:
    double minAreaFreeRect(vector<vector<int>>& points) {
        int n = points.size();
        set<pair<long long,long long>> s;
        for (auto& p : points) s.insert({p[0], p[1]});
        double best = 1e18;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                if (j == i) continue;
                long long dx1 = points[j][0]-points[i][0], dy1 = points[j][1]-points[i][1];
                for (int k = j+1; k < n; k++) {
                    if (k == i) continue;
                    long long dx2 = points[k][0]-points[i][0], dy2 = points[k][1]-points[i][1];
                    if (dx1*dx2 + dy1*dy2 != 0) continue;
                    long long px = points[j][0]+points[k][0]-points[i][0];
                    long long py = points[j][1]+points[k][1]-points[i][1];
                    if (!s.count({px, py})) continue;
                    best = min(best, sqrt((double)(dx1*dx1+dy1*dy1)) * sqrt((double)(dx2*dx2+dy2*dy2)));
                }
            }
        return best > 1e17 ? 0.0 : best;
    }
};

