class Solution {
    public double minAreaFreeRect(int[][] points) {
        int n = points.length;
        Set<Long> set = new HashSet<>();
        for (int[] p : points) set.add(encode(p[0], p[1]));
        double best = Double.MAX_VALUE;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                if (j == i) continue;
                long dx1 = points[j][0]-points[i][0], dy1 = points[j][1]-points[i][1];
                for (int k = j+1; k < n; k++) {
                    if (k == i) continue;
                    long dx2 = points[k][0]-points[i][0], dy2 = points[k][1]-points[i][1];
                    if (dx1*dx2 + dy1*dy2 != 0) continue;
                    long px = points[j][0]+points[k][0]-points[i][0];
                    long py = points[j][1]+points[k][1]-points[i][1];
                    if (!set.contains(encode(px, py))) continue;
                    best = Math.min(best, Math.sqrt(dx1*dx1+dy1*dy1) * Math.sqrt(dx2*dx2+dy2*dy2));
                }
            }
        return best == Double.MAX_VALUE ? 0.0 : best;
    }
    private long encode(long x, long y) { return x * 100001L + y; }
}

