class Solution {
public:
    double minAreaFreeRect(vector<vector<int>>& points) {
        int n = points.size();
        map<tuple<long long,long long,long long>, vector<pair<int,int>>> groups;
        for (int i = 0; i < n; i++)
            for (int j = i+1; j < n; j++) {
                long long cx = points[i][0] + points[j][0];
                long long cy = points[i][1] + points[j][1];
                long long dx = points[i][0] - points[j][0], dy = points[i][1] - points[j][1];
                groups[{cx, cy, dx*dx + dy*dy}].push_back({i, j});
            }
        double best = 1e18;
        for (auto& [k, v] : groups)
            for (size_t a = 0; a < v.size(); a++)
                for (size_t b = a+1; b < v.size(); b++) {
                    auto& [i1, j1] = v[a]; auto& [i2, j2] = v[b];
                    double d1 = hypot(points[i1][0]-points[i2][0], points[i1][1]-points[i2][1]);
                    double d2 = hypot(points[i1][0]-points[j2][0], points[i1][1]-points[j2][1]);
                    best = min(best, d1 * d2);
                }
        return best > 1e17 ? 0.0 : best;
    }
};

