class Solution {
    public double minAreaFreeRect(int[][] points) {
        int n = points.length;
        Map<Long, List<int[]>> groups = new HashMap<>();
        for (int i = 0; i < n; i++)
            for (int j = i+1; j < n; j++) {
                long cx = points[i][0] + points[j][0];
                long cy = points[i][1] + points[j][1];
                long dx = points[i][0] - points[j][0], dy = points[i][1] - points[j][1];
                long key = (cx << 40) ^ (cy << 20) ^ (dx*dx + dy*dy);
                groups.computeIfAbsent(key, z -> new ArrayList<>()).add(new int[]{i, j});
            }
        double best = Double.MAX_VALUE;
        for (List<int[]> v : groups.values())
            for (int a = 0; a < v.size(); a++)
                for (int b = a+1; b < v.size(); b++) {
                    int[] e1 = v.get(a), e2 = v.get(b);
                    double d1 = Math.hypot(points[e1[0]][0]-points[e2[0]][0], points[e1[0]][1]-points[e2[0]][1]);
                    double d2 = Math.hypot(points[e1[0]][0]-points[e2[1]][0], points[e1[0]][1]-points[e2[1]][1]);
                    best = Math.min(best, d1 * d2);
                }
        return best == Double.MAX_VALUE ? 0.0 : best;
    }
}

