var minAreaFreeRect = function(points) {
    const n = points.length;
    const groups = new Map();
    for (let i = 0; i < n; i++)
        for (let j = i+1; j < n; j++) {
            const cx = points[i][0] + points[j][0];
            const cy = points[i][1] + points[j][1];
            const dx = points[i][0] - points[j][0], dy = points[i][1] - points[j][1];
            const key = cx + ',' + cy + ',' + (dx*dx + dy*dy);
            if (!groups.has(key)) groups.set(key, []);
            groups.get(key).push([i, j]);
        }
    let best = Infinity;
    for (const v of groups.values())
        for (let a = 0; a < v.length; a++)
            for (let b = a+1; b < v.length; b++) {
                const [i1, j1] = v[a], [i2, j2] = v[b];
                const d1 = Math.hypot(points[i1][0]-points[i2][0], points[i1][1]-points[i2][1]);
                const d2 = Math.hypot(points[i1][0]-points[j2][0], points[i1][1]-points[j2][1]);
                best = Math.min(best, d1 * d2);
            }
    return best === Infinity ? 0 : best;
};
